  console.log("script parse ok");
} catch (e) {
  console.log("script parse check skipped/failed:", e.message);
  process.exit(1);
}

// $t key 收集
const keys = new Set();
const re = /\$t\(\s*'([^']+)'/g;
let m;
while ((m = re.exec(src))) keys.add(m[1]);
console.log("static $t keys:", [...keys].sort().join(", "));
console.log("dynamic prefix keys: rd.property.tabs.");

function loadMod(p) {
  const text = fs.readFileSync(p, "utf8");
  const body = text.replace(/^export default/, "module.exports =");
  const mod = { exports: {} };
  new Function("module", "exports", body)(mod, mod.exports);
  return mod.exports;
}
const zh = loadMod(path.join(__dirname, "src/i18n/lang/zh-CN/rd.js"));
const en = loadMod(path.join(__dirname, "src/i18n/lang/en-US/rd.js"));

function flat(obj, prefix, out) {
  Object.keys(obj).forEach((k) => {
    const v = obj[k];
    const key = prefix ? prefix + "." + k : k;
    if (v && typeof v === "object") flat(v, key, out);
    else out[key] = v;
  });
  return out;
}
const fz = flat(zh, "rd", {});
const fe = flat(en, "rd", {});
const zk = Object.keys(fz).sort();
const ek = Object.keys(fe).sort();
console.log("zh keys:", zk.join(", "));
console.log("en keys:", ek.join(", "));
console.log("structure in sync:", JSON.stringify(zk) === JSON.stringify(ek));
const missing = ek.filter((k) => zk.indexOf(k) === -1);
const extra = zk.filter((k) => ek.indexOf(k) === -1);
console.log("missing in zh:", missing, "extra in zh:", extra);
const unresolved = [...keys].filter((k) => !(k in fz));
console.log("unresolved static keys:", unresolved);
["globalPatent", "inventionPatent", "utilityModelPatent"].forEach((t) => {
  const k = "rd.property.tabs." + t;
  if (!(k in fz) || !(k in fe)) console.log("MISSING dynamic key", k);
});
console.log("en values verbatim check:");
console.log(JSON.stringify(fe, null, 1));
